/* Waxlight Wiki — shared chrome: header, sidebar, footer, TOC, prev/next, search.
 * Navigation data comes from assets/wiki-data.js, generated by wiki/build.mjs
 * from the Markdown files in content/. Do not add pages here. */
(function () {
  "use strict";

  var LINKS = {
    discord: "https://discord.gg/CrRHvg9UVw",
    github: "https://github.com/AmadoMuerte/Waxlight-launcher",
    releases: "https://github.com/AmadoMuerte/Waxlight-launcher/releases/latest",
    issues: "https://github.com/AmadoMuerte/Waxlight-launcher/issues",
    support: "https://hipolink.net/amadomuerte"
  };

  var DATA = window.WIKI_DATA;
  if (!DATA || !DATA.langs) return;

  /* Language from path: .../wiki/<lang>/<page>.html */
  var langMatch = location.pathname.match(/\/(ru|en)\//);
  var LANG = langMatch && DATA.langs[langMatch[1]] ? langMatch[1] : "en";
  var langData = DATA.langs[LANG];

  /* Depth: <lang>/x.html -> "../", <lang>/<section>/x.html -> "../../" */
  var inGroup = /\/(ru|en)\/[^/]+\//.test(location.pathname);
  var base = inGroup ? "../../" : "../";

  var STR = {
    ru: {
      searchPlaceholder: "Поиск по wiki…",
      searchLabel: "Поиск по wiki",
      searchEmpty: "Ничего не найдено",
      toc: "На этой странице",
      menu: "Меню",
      download: "Скачать",
      support: "Поддержать",
      discordSidebar: "Официальный Discord",
      prev: "← Назад",
      next: "Вперёд →",
      footerAbout:
        "Независимый открытый лаунчер для Vintage Story. Не аффилирован с Anego Studios и разработчиками Vintage Story.",
      footerProject: "Проект",
      footerIssue: "Сообщить о проблеме",
      footerSupport: "Поддержать проект",
      footerCommunity: "Сообщество",
      footerDiscord: "Discord-сервер",
      footerPolicies: "Политики",
      footerPrivacy: "Конфиденциальность",
      footerSecurity: "Безопасность",
      footerSigning: "Подпись кода",
      footerDocs: "Все документы",
      footerLicense: "Waxlight распространяется по лицензии GPL-3.0."
    },
    en: {
      searchPlaceholder: "Search the wiki…",
      searchLabel: "Search the wiki",
      searchEmpty: "Nothing found",
      toc: "On this page",
      menu: "Menu",
      download: "Download",
      support: "Support",
      discordSidebar: "Official Discord",
      prev: "← Previous",
      next: "Next →",
      footerAbout:
        "An independent open-source launcher for Vintage Story. Not affiliated with or endorsed by Anego Studios or the developers of Vintage Story.",
      footerProject: "Project",
      footerIssue: "Report an issue",
      footerSupport: "Support the project",
      footerCommunity: "Community",
      footerDiscord: "Discord server",
      footerPolicies: "Policies",
      footerPrivacy: "Privacy",
      footerSecurity: "Security",
      footerSigning: "Code signing",
      footerDocs: "All documents",
      footerLicense: "Waxlight is licensed under GPL-3.0."
    }
  };
  var T = STR[LANG];

  var pageId = document.body.getAttribute("data-page") || "";

  var DISCORD_SVG =
    '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.32 4.37a19.8 19.8 0 0 0-4.93-1.51 13.8 13.8 0 0 0-.64 1.28 18.3 18.3 0 0 0-5.5 0 13.8 13.8 0 0 0-.64-1.28c-1.71.29-3.37.8-4.93 1.51A20.3 20.3 0 0 0 .1 18.06a19.9 19.9 0 0 0 6.07 3.03c.49-.66.93-1.37 1.3-2.1a12.9 12.9 0 0 1-2.05-.98c.17-.12.34-.25.5-.38a14.2 14.2 0 0 0 12.16 0c.16.13.33.26.5.38-.65.39-1.34.72-2.05.98.37.73.81 1.44 1.3 2.1a19.9 19.9 0 0 0 6.07-3.03 20.3 20.3 0 0 0-3.58-13.69ZM8.02 15.33c-1.18 0-2.16-1.08-2.16-2.42s.95-2.42 2.16-2.42 2.18 1.09 2.16 2.42c0 1.34-.95 2.42-2.16 2.42Zm7.96 0c-1.18 0-2.16-1.08-2.16-2.42s.95-2.42 2.16-2.42 2.18 1.09 2.16 2.42c0 1.34-.95 2.42-2.16 2.42Z"/></svg>';
  var HEART_SVG =
    '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>';

  function el(html) {
    var t = document.createElement("template");
    t.innerHTML = html.trim();
    return t.content.firstElementChild;
  }

  function pageUrl(page) {
    return base + LANG + "/" + page.path;
  }

  function sectionTitle(sectionId) {
    var s = langData.sections.find(function (x) { return x.id === sectionId; });
    return s ? s.title : sectionId;
  }

  /* Navigation model: unsectioned pages first, then sections in generated order. */
  var rootPages = langData.pages.filter(function (p) { return !p.section; });
  var navGroups = [{ title: "", pages: rootPages }].concat(
    langData.sections.map(function (s) {
      return {
        title: s.title,
        pages: langData.pages.filter(function (p) { return p.section === s.id; })
      };
    }).filter(function (g) { return g.pages.length > 0; })
  );
  var flatPages = [];
  navGroups.forEach(function (g) { g.pages.forEach(function (p) { flatPages.push(p); }); });

  var currentPage = null;
  flatPages.forEach(function (p, i) {
    if (p.slug === pageId) currentPage = { page: p, index: i };
  });

  /* Same page in the other language */
  function altLangUrl(target) {
    return location.pathname.replace("/" + LANG + "/", "/" + target + "/") + location.hash;
  }

  /* Header */
  var header = el(
    '<header class="site-header"><div class="wrap">' +
      '<button class="menu-toggle" type="button" aria-label="' + T.menu + '">☰</button>' +
      '<a class="brand" href="' + base + LANG + '/index.html">' +
        '<img src="' + base + 'assets/waxlight.png" alt="Waxlight">' +
        '<span>Waxlight<br><small>Wiki</small></span>' +
      '</a>' +
      '<div class="header-search"><input id="wiki-search" type="search" placeholder="' + T.searchPlaceholder + '" autocomplete="off" aria-label="' + T.searchLabel + '">' +
      '<div class="search-results" id="wiki-search-results" role="listbox"></div></div>' +
      '<nav class="header-links" aria-label="Links">' +
        '<a class="discord" href="' + LINKS.discord + '" target="_blank" rel="noopener">' + DISCORD_SVG + '<span>Discord</span></a>' +
        '<a class="donate" href="' + LINKS.support + '" target="_blank" rel="noopener">' + HEART_SVG + '<span>' + T.support + '</span></a>' +
        '<a href="' + LINKS.github + '" target="_blank" rel="noopener"><span>GitHub</span></a>' +
        '<a href="' + LINKS.releases + '" target="_blank" rel="noopener"><span>' + T.download + '</span></a>' +
        '<span class="lang-switch">' +
          '<a href="' + altLangUrl("ru") + '"' + (LANG === "ru" ? ' class="active"' : "") + '>RU</a>' +
          '<a href="' + altLangUrl("en") + '"' + (LANG === "en" ? ' class="active"' : "") + '>EN</a>' +
        '</span>' +
      '</nav>' +
    '</div></header>'
  );
  document.body.prepend(header);

  /* Sidebar */
  var navHtml = navGroups.map(function (g) {
    var links = g.pages.map(function (p) {
      var active = p.slug === pageId ? ' class="active" aria-current="page"' : "";
      return "<a" + active + ' href="' + pageUrl(p) + '">' + p.title + "</a>";
    }).join("");
    var title = g.title ? '<p class="nav-group-title">' + g.title + "</p>" : "";
    return '<div class="nav-group">' + title + links + "</div>";
  }).join("");

  var sidebar = el(
    '<aside class="sidebar"><nav aria-label="Wiki">' + navHtml + "</nav>" +
      '<a class="sidebar-discord" href="' + LINKS.discord + '" target="_blank" rel="noopener">' + DISCORD_SVG +
      "<span>" + T.discordSidebar + "<small>discord.gg/CrRHvg9UVw</small></span></a>" +
    "</aside>"
  );

  var main = document.querySelector(".wiki-main");
  var layout = el('<div class="layout"></div>');
  main.parentNode.insertBefore(layout, main);
  layout.appendChild(sidebar);
  layout.appendChild(main);

  /* TOC (skip headings inside cards and the community banner) */
  var headings = Array.prototype.filter.call(
    main.querySelectorAll(".wiki-content h2, .wiki-content h3"),
    function (h) { return !h.closest(".card, .community-banner"); }
  );
  if (headings.length > 1) {
    var tocLinks = "";
    headings.forEach(function (h, i) {
      if (!h.id) h.id = "sec-" + i;
      var depth = h.tagName === "H3" ? " depth-3" : "";
      tocLinks += '<a class="toc-link' + depth + '" href="#' + h.id + '">' + h.textContent + "</a>";
    });
    var toc = el('<aside class="toc"><p class="toc-title">' + T.toc + '</p><nav aria-label="TOC">' + tocLinks + "</nav></aside>");
    layout.appendChild(toc);
  }

  /* Breadcrumb */
  if (currentPage && pageId !== "index") {
    var section = currentPage.page.section;
    var middle = section ? sectionTitle(section) + " / " : "";
    var crumb = el(
      '<nav class="breadcrumb" aria-label="Breadcrumb"><a href="' + base + LANG + '/index.html">Wiki</a> / ' +
        middle + currentPage.page.title + "</nav>"
    );
    var content = main.querySelector(".wiki-content");
    content.parentNode.insertBefore(crumb, content);
  }

  /* Prev / next */
  if (currentPage && flatPages.length > 1) {
    var prev = flatPages[currentPage.index - 1];
    var next = flatPages[currentPage.index + 1];
    if (prev || next) {
      var prevHtml = prev
        ? '<a class="prev" href="' + pageUrl(prev) + '"><span>' + T.prev + '</span><strong>' + prev.title + "</strong></a>"
        : "<span></span>";
      var nextHtml = next
        ? '<a class="next" href="' + pageUrl(next) + '"><span>' + T.next + '</span><strong>' + next.title + "</strong></a>"
        : "<span></span>";
      main.querySelector(".wiki-content").appendChild(el('<nav class="prev-next" aria-label="Pagination">' + prevHtml + nextHtml + "</nav>"));
    }
  }

  /* Footer */
  var footer = el(
    '<footer class="site-footer"><div class="wrap">' +
      "<div><h4>Waxlight Launcher</h4><p>" + T.footerAbout + "</p></div>" +
      "<div><h4>" + T.footerProject + "</h4>" +
        '<a href="' + LINKS.releases + '" target="_blank" rel="noopener">' + T.download + "</a>" +
        '<a href="' + LINKS.github + '" target="_blank" rel="noopener">GitHub</a>' +
        '<a href="' + LINKS.issues + '" target="_blank" rel="noopener">' + T.footerIssue + "</a>" +
        '<a href="' + LINKS.support + '" target="_blank" rel="noopener">' + T.footerSupport + "</a></div>" +
      "<div><h4>" + T.footerCommunity + "</h4>" +
        '<a href="' + LINKS.discord + '" target="_blank" rel="noopener">' + T.footerDiscord + "</a>" +
        '<a href="' + base + LANG + '/faq.html">FAQ</a></div>' +
      "<div><h4>" + T.footerPolicies + "</h4>" +
        '<a href="' + base + LANG + '/policies/privacy.html">' + T.footerPrivacy + "</a>" +
        '<a href="' + base + LANG + '/policies/security.html">' + T.footerSecurity + "</a>" +
        '<a href="' + base + LANG + '/policies/code-signing.html">' + T.footerSigning + "</a>" +
        '<a href="' + base + LANG + '/documents.html">' + T.footerDocs + "</a></div>" +
    "</div>" +
    '<div class="footer-bottom"><span>' + T.footerLicense + "</span><span>© 2026 AmadoMuerte</span></div>" +
    "</footer>"
  );
  document.body.appendChild(footer);

  /* Mobile menu */
  document.querySelector(".menu-toggle").addEventListener("click", function () {
    document.body.classList.toggle("nav-open");
  });
  sidebar.addEventListener("click", function (e) {
    if (e.target.closest("a")) document.body.classList.remove("nav-open");
  });

  /* Search over generated page metadata */
  var index = flatPages.map(function (p) {
    return {
      title: p.title,
      group: p.section ? sectionTitle(p.section) : "",
      path: p.path,
      hay: (p.title + " " + p.description + " " + (p.section ? sectionTitle(p.section) : "")).toLowerCase()
    };
  });
  var input = document.getElementById("wiki-search");
  var results = document.getElementById("wiki-search-results");
  if (input && results) {
    input.addEventListener("input", function () {
      var q = input.value.trim().toLowerCase();
      if (q.length < 2) { results.classList.remove("open"); results.innerHTML = ""; return; }
      var terms = q.split(/\s+/);
      var hits = index.filter(function (e) {
        return terms.every(function (t) { return e.hay.indexOf(t) !== -1; });
      }).slice(0, 8);
      results.innerHTML = hits.length
        ? hits.map(function (h) {
            return '<a href="' + base + LANG + "/" + h.path + '">' + h.title + (h.group ? "<small>" + h.group + "</small>" : "") + "</a>";
          }).join("")
        : '<div class="empty">' + T.searchEmpty + "</div>";
      results.classList.add("open");
    });
    input.addEventListener("keydown", function (e) {
      if (e.key === "Enter") {
        var first = results.querySelector("a");
        if (first) location.href = first.href;
      }
      if (e.key === "Escape") { results.classList.remove("open"); input.blur(); }
    });
    document.addEventListener("click", function (e) {
      if (!e.target.closest(".header-search")) results.classList.remove("open");
    });
  }
})();
